	if ruleOr(ruleKnown(string(x.Status) != string("exited")), ruleAnd(ruleKnown(x.ValidTo != nil), ruleKnown(x.ExitReasonCode != nil))) == ruleFalse {
		return hrerrors.Invalid("hr_talent_pool_memberships", "ck_hr_pool_membership_exit")
	}
